4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code householdSize}: the number of owners in this owner's household
9	 * (owners sharing the same non-null {@code householdId}) counted <em>after</em> this create —
10	 * the existing members plus the owner being created. When the owner has no {@code householdId}
11	 * (not in a shared household), the size is 1.
12	 *
13	 * <p>Runs after {@link AssignHousehold} (so the {@code householdId} and any backfilled members
14	 * are settled) but before {@link SaveOwner} (so the owner being created is not itself in the
15	 * repository yet and is instead counted explicitly), mutating the owner in place so the
